// --- Helpers ---

export function getExercise(slug: string): Exercise | undefined {
  return exercises.find(e => e.slug === slug);
}

// Normaliza texto (NFD, sin acentos, minúsculas, sin símbolos).
function normalize(text: string): string {
  return text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

export interface SearchFilters {
  q?: string;
  equipment?: string;
  primaryMuscle?: string;
  exerciseType?: string;
  isStretch?: boolean | null;
}

export function searchExercises(filters: SearchFilters = {}): Exercise[] {
  const q = normalize(filters.q || '');
  const tokens = q ? q.split(' ').filter(Boolean) : [];
  return exercises.filter(e => {
    if (filters.equipment && filters.equipment !== 'all' && e.equipment !== filters.equipment) return false;
    if (filters.primaryMuscle && filters.primaryMuscle !== 'all' && e.primaryMuscle !== filters.primaryMuscle) return false;
    if (filters.exerciseType && filters.exerciseType !== 'all' && e.exerciseType !== filters.exerciseType) return false;
    if (filters.isStretch != null && e.isStretch !== filters.isStretch) return false;
    if (tokens.length) {
      const hay = normalize(
        [e.name, e.nameEn, e.equipment, e.primaryMuscle, ...e.secondaryMuscles, e.exerciseTypeLabel].join(' ')
      );
      return tokens.every(t => hay.includes(t));
    }
    return true;
  });
}
